from pathlib import Path
import re,html,markdown
ROOT=Path(__file__).resolve().parents[1]
files=sorted(ROOT.glob('[0-9][0-9]_*.md'))+[ROOT/'database/DATA_DICTIONARY.md',ROOT/'adrs/001_产品基线与差异.md',ROOT/'adrs/002_工程决策.md',ROOT/'sources/参考资料与采用范围.md']
ids={p.resolve():'doc-'+str(i) for i,p in enumerate(files)};nav=[];articles=[]
for i,p in enumerate(files):
 text=p.read_text();md=markdown.Markdown(extensions=['tables','fenced_code','toc','sane_lists']);body=md.convert(text);docid=ids[p.resolve()]
 body=re.sub(r'id="([^"]+)"',lambda m:'id="'+docid+'-'+m.group(1)+'"',body)
 def link(m):
  attr,url=m.groups()
  if url.startswith(('http:','https:','mailto:','#')):
   if url.startswith('#'):url='#'+docid+'-'+url[1:]
   return f'{attr}="{url}"'
  dest=(p.parent/url.split('#')[0]).resolve();base=str(dest.relative_to(ROOT.resolve())) if dest.is_relative_to(ROOT.resolve()) else url
  if dest in ids:base='#'+ids[dest]+('-'+url.split('#',1)[1] if '#' in url else '')
  return f'{attr}="{html.escape(base)}"'
 body=re.sub(r'(href|src)="([^"]+)"',link,body)
 body=body.replace('<table>','<div class="table-wrap"><table>').replace('</table>','</table></div>')
 body=re.sub(r'<img ([^>]*?)src="([^"]+)"([^>]*)>',lambda m:f'<a class="figure" href="{m.group(2)}" target="_blank"><img {m.group(1)}src="{m.group(2)}"{m.group(3)}></a>',body)
 title=text.splitlines()[0].lstrip('# ').replace('LAST MILE ','')
 h2=re.findall(r'<h2 id="([^"]+)">(.*?)</h2>',body)
 nav.append(f'<details {"open" if i<3 else ""}><summary><a href="#{docid}">{html.escape(title)}</a></summary><div>'+''.join(f'<a href="#{a}">{re.sub("<[^>]+>","",b)}</a>' for a,b in h2)+'</div></details>')
 articles.append(f'<article id="{docid}"><div class="source">SOURCE <a href="{p.relative_to(ROOT)}">{p.relative_to(ROOT)}</a></div>{body}</article>')
css='''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:26px}body{margin:0;background:#edf1f5;color:#172d45;font:15px/1.8 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}aside{position:fixed;inset:0 auto 0 0;width:285px;background:#142b45;color:#deebfa;overflow:auto;padding:28px 20px}aside h1{font:700 23px/1.2 system-ui;margin:0}aside .sub{font:12px/1.8 monospace;color:#93adca;margin:12px 0 28px}aside a{color:#dce9f8;text-decoration:none}details{margin:0 0 16px}summary{font-weight:600;cursor:pointer;font-size:13px}details div{border-left:1px solid #405570;margin:8px 0 0 5px;padding-left:12px}details div a{display:block;font-size:12px;line-height:1.6;padding:4px 0;color:#9cb5cf}main{margin-left:285px;padding:35px 42px;max-width:1510px}.hero{padding:44px;background:#fff;border-top:6px solid #387bac;border-radius:9px;margin-bottom:28px}.eyebrow{font:12px monospace;letter-spacing:3px;color:#48708e}.hero h1{font-size:38px;line-height:1.25;margin:16px 0}.hero p{max-width:780px;color:#546579}.tags{display:flex;gap:9px;flex-wrap:wrap}.tags span{background:#edf4fb;color:#31577c;border-radius:5px;padding:5px 10px;font-size:12px}article{background:#fff;padding:35px 42px;border:1px solid #dde4ed;border-radius:9px;margin:0 0 26px;scroll-margin-top:26px}.source{font:11px monospace;color:#77879a;letter-spacing:.5px;border-bottom:1px solid #e5eaf1;padding-bottom:18px;margin-bottom:25px}h1{font-size:28px;line-height:1.4}h2{font-size:21px;margin:40px 0 15px;border-bottom:2px solid #e7edf5;padding-bottom:10px}h3{font-size:17px;margin-top:28px}a{color:#256495}p{margin:12px 0}li{margin:4px 0}code{font:12px/1.7 ui-monospace,SFMono-Regular,Menlo,monospace;background:#f0f4f8;padding:2px 4px;border-radius:3px;overflow-wrap:anywhere}pre{background:#152a40;color:#e6edf5;padding:20px;border-radius:8px;overflow:auto;line-height:1.6}pre code{background:none;padding:0;color:inherit}.table-wrap{overflow:auto;margin:18px 0;border:1px solid #dce5ed;border-radius:6px}table{width:100%;border-collapse:collapse;font-size:13px;min-width:640px}th{text-align:left;background:#eaf1f8;font-weight:650}th,td{padding:12px 13px;vertical-align:top;border-bottom:1px solid #e4ebf2;line-height:1.7}tr:last-child td{border-bottom:0}tr:nth-child(even) td{background:#fafcfd}.figure{display:block;border:1px solid #e3eaf1;border-radius:8px;overflow:hidden;margin:22px 0;cursor:zoom-in}.figure img{width:100%;display:block}blockquote{border-left:3px solid #80a6c9;margin-left:0;padding-left:18px;color:#586d80}.top{position:fixed;right:20px;bottom:20px;border-radius:22px;padding:8px 14px;background:#2c6088;color:white;text-decoration:none;font-size:12px}@media(max-width:1000px){aside{position:relative;width:auto;max-height:300px}main{margin:0;padding:18px}article,.hero{padding:24px}}@media print{aside,.top{display:none}main{margin:0;padding:0;max-width:none}body{background:white}article{border:0;page-break-before:always}table{min-width:0;font-size:10px}pre{white-space:pre-wrap}h2,h3{break-after:avoid}}'''
page='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LAST MILE · 工程设计手册 v0.5</title><style>'+css+'</style></head><body id="top"><aside><h1>LAST MILE</h1><div class="sub">ENGINEERING DESIGN / v0.5<br>PRD · HLD · LLD · CONTRACTS<br>使用浏览器查找搜索全文</div>'+''.join(nav)+'</aside><main><section class="hero"><div class="eyebrow">REFERENCE DESIGN · 2026.09.16</div><h1>从玩法方案到<br>可实施的工程规格</h1><p>完整产品基线、模块边界、数据库与 API、双 Agent 运行协议、预写剧情及验证证据。点击图纸可放大，目录可跳转到任意章节。</p><div class="tags"><span>单人参考配置 · 产品待签定</span><span>8 页可编辑 draw.io</span><span>23 个公开 API</span><span>设计契约已验证 · 游戏未实现</span></div></section>'+''.join(articles)+'</main><a class="top" href="#top">回到顶部 ↑</a></body></html>'
(ROOT/'设计手册.html').write_text(page)
print('HTML handbook:',len(files),'documents',len(page),'characters')
